func (s *Server) getJob(w http.ResponseWriter, r *http.Request) {
	if !s.ownJob(w, r) {
		return
	}
	v, e := s.S.One(`SELECT * FROM jobs WHERE id=$1`, num(r, "id"))
	if e != nil {
		fail(w, 404, "job_not_found", e)
		return
	}
	write(w, 200, v)
}
func (s *Server) attempts(w http.ResponseWriter, r *http.Request) {
	if !s.ownJob(w, r) {
		return
	}
	v, e := s.S.Rows(`SELECT * FROM attempts WHERE job_id=$1 ORDER BY n`, num(r, "id"))
	output(w, map[string]any{"attempts": v}, e)
}
func (s *Server) deleteJob(w http.ResponseWriter, r *http.Request) {
	if !s.ownJob(w, r) {
		return
	}
	res, e := s.S.DB.Exec(`WITH removed AS (DELETE FROM jobs WHERE id=$1 AND state IN ('succeeded','dead','cancelled') RETURNING *) INSERT INTO job_events(job_id,namespace_id,at,event,queue,worker,attempt) SELECT r.id,r.namespace_id,$2,'deleted',q.name,r.leased_by,r.attempts FROM removed r JOIN queues q ON q.id=r.queue_id`, num(r, "id"), s.Clock.Now())
	if e = jobs.Changed(res, e); e != nil {
		fail(w, 409, "state_conflict", e)
		return
	}
	write(w, 204, nil)
}
func (s *Server) jobVerb(w http.ResponseWriter, r *http.Request) {
	if !s.ownJob(w, r) {
		return
	}
	id := num(r, "id")
	now := s.Clock.Now()
	var e error
	switch r.PathValue("verb") {
	case "cancel":
		e = s.Jobs.Cancel(id, now)
	case "retry":
		e = s.Jobs.Retry(id, now)
	case "ack", "nack", "heartbeat":
		var in struct {
			LeaseToken    string `json:"lease_token"`
			Result        any    `json:"result"`
			Error         string `json:"error"`
			Retry         *bool  `json:"retry"`
			DelaySeconds  *int   `json:"delay_seconds"`
			ExtendSeconds int    `json:"extend_seconds"`
		}
		if !decode(w, r, &in) {
			return
		}
		switch r.PathValue("verb") {
		case "ack":
			if containsNUL(in.Result) {
				fail(w, 400, "invalid_result", "result cannot contain U+0000")
				return
			}
			e = s.Jobs.Ack(id, in.LeaseToken, in.Result, now)
		case "nack":
			if strings.ContainsRune(in.Error, 0) {
				fail(w, 400, "invalid_error", "error cannot contain U+0000")
				return
			}
			if in.DelaySeconds != nil && (*in.DelaySeconds < 0 || *in.DelaySeconds > jobs.MaxSeconds) {
				fail(w, 400, "invalid_delay", "delay_seconds must be 0–2147483647")
				return
			}
			retry := true
			if in.Retry != nil {
				retry = *in.Retry
			}
			e = s.Jobs.Nack(id, in.LeaseToken, in.Error, retry, in.DelaySeconds, now)
		case "heartbeat":
			if in.ExtendSeconds < 1 || in.ExtendSeconds > jobs.MaxSeconds {
				fail(w, 400, "invalid_extension", "extend_seconds must be 1–2147483647")
				return
			}
			e = s.Jobs.Heartbeat(id, in.LeaseToken, in.ExtendSeconds, now)
		}
	default:
		fail(w, 404, "not_found", "unknown operation")
		return
	}
	if e != nil {
		fail(w, 409, "state_conflict", e)
		return
	}
	write(w, 200, map[string]any{"ok": true})
}
func (s *Server) createWorker(w http.ResponseWriter, r *http.Request) {
	var in struct {
		Name  string   `json:"name"`
		Kinds []string `json:"kinds"`
	}
	if !decode(w, r, &in) {
		return
	}
	if in.Name == "" || len(in.Kinds) == 0 {
		fail(w, 400, "invalid_worker", "name and kinds required")
		return
	}
	token := jobs.Token()
	var id int64
	e := s.S.DB.QueryRow(`INSERT INTO workers(namespace_id,name,kinds,token,last_seen_at) VALUES($1,$2,$3,$4,$5) RETURNING id`, ident(r).Namespace, in.Name, pq.Array(in.Kinds), token, s.Clock.Now()).Scan(&id)
	if e != nil {
		fail(w, 500, "database_error", e)
		return
	}
	write(w, 201, map[string]any{"worker_id": id, "token": token})
}
func (s *Server) deleteWorker(w http.ResponseWriter, r *http.Request) {
	tx, e := s.S.DB.Begin()
	if e != nil {
		fail(w, 500, "database_error", e)
		return
	}
	defer tx.Rollback()
	res, e := tx.Exec(`DELETE FROM workers WHERE id=$1 AND namespace_id=$2`, num(r, "id"), ident(r).Namespace)
	if e = jobs.Changed(res, e); e != nil {
		fail(w, 404, "worker_not_found", e)
		return
	}
	now := s.Clock.Now()
	dead, e := s.Jobs.ReleaseWorker(tx, num(r, "id"), now)
	if e == nil {
		e = tx.Commit()
	}
	for _, id := range dead {
		if e == nil {
			e = s.Jobs.Notify(id, now)
		}
	}
	output(w, map[string]any{"ok": true}, e)
}
func (s *Server) lease(w http.ResponseWriter, r *http.Request, q map[string]any) {
	var in struct {
		WorkerID int64 `json:"worker_id"`
		MaxJobs  int   `json:"max_jobs"`
	}
	in.MaxJobs = 1
	if !decode(w, r, &in) {
		return
	}
	if in.MaxJobs < 1 || in.MaxJobs > 100 {
		fail(w, 400, "invalid_batch", "max_jobs must be 1–100")
		return
	}
	var exists bool
	s.S.DB.QueryRow(`SELECT EXISTS(SELECT 1 FROM workers WHERE id=$1 AND namespace_id=$2)`, in.WorkerID, ident(r).Namespace).Scan(&exists)
	if !exists {
		fail(w, 404, "worker_not_found", "unknown worker")
		return
	}
	v, e := s.Jobs.Lease(q["id"].(int64), in.WorkerID, in.MaxJobs, s.Clock.Now())
	output(w, map[string]any{"jobs": v}, e)
}

func (s *Server) ownJob(w http.ResponseWriter, r *http.Request) bool {
	var id int64
	e := s.S.DB.QueryRow(`SELECT id FROM jobs WHERE id=$1 AND namespace_id=$2`, num(r, "id"), ident(r).Namespace).Scan(&id)
	if e == sql.ErrNoRows {
		fail(w, 404, "job_not_found", "job not found")
		return false
	}
	if e != nil {
		fail(w, 500, "database_error", e)
		return false
	}
	return true
}

// JSON strings and object keys can contain NUL; PostgreSQL jsonb cannot.
func containsNUL(v any) bool {
	switch x := v.(type) {
	case string:
		return strings.ContainsRune(x, 0)
	case []any:
		for _, value := range x {
			if containsNUL(value) {
				return true
			}
		}
	case map[string]any:
		for key, value := range x {
			if strings.ContainsRune(key, 0) || containsNUL(value) {
				return true
			}
		}
	}
	return false
}
package jobs

import "time"

func (j *Service) Cancel(id int64, now time.Time) error {
	r, e := j.S.DB.Exec(`UPDATE jobs SET state='cancelled',event_at=$2,finished_at=$2,lease_token=NULL,leased_by=NULL,lease_expires_at=NULL WHERE id=$1 AND state NOT IN ('succeeded','dead','cancelled')`, id, now)
	if e = Changed(r, e); e != nil {
		return e
	}
	return j.Notify(id, now)
}
func (j *Service) Retry(id int64, now time.Time) error {
	r, e := j.S.DB.Exec(`UPDATE jobs SET state='queued',event_at=$2,attempts=0,run_at=$2,finished_at=NULL,purge_requested=false WHERE id=$1 AND state='dead'`, id, now)
	return Changed(r, e)
}
package jobs

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"time"
)

func (j *Service) Ack(id int64, token string, result any, now time.Time) error {
	b, _ := json.Marshal(result)
	// The joined row is the pre-update snapshot: it still names the holder.
	var worker int64
	e := j.S.DB.QueryRow(`UPDATE jobs j SET state='succeeded',event_at=$3,result=$2,finished_at=$3,attempts=j.attempts+1,lease_token=NULL,leased_by=NULL,lease_expires_at=NULL FROM jobs o WHERE o.id=j.id AND j.id=$1 AND j.state='leased' AND j.lease_token=$4 AND j.lease_expires_at > $3 RETURNING o.leased_by`, id, string(b), now, token).Scan(&worker)
	if e == sql.ErrNoRows {
		return fmt.Errorf("state conflict")
	}
	if e != nil {
		return e
	}
	_, e = j.S.DB.Exec(`INSERT INTO attempts SELECT id,(SELECT count(*)+1 FROM attempts WHERE job_id=$1),$3,leased_at,$2,'succeeded','' FROM jobs WHERE id=$1`, id, now, worker)
	if e != nil {
		return e
	}
	return j.Notify(id, now)
}
package jobs

import "time"

func (j *Service) Nack(id int64, token, message string, retry bool, delay *int, now time.Time) error {
	tx, e := j.S.DB.Begin()
	if e != nil {
		return e
	}
	defer tx.Rollback()
	var attempts, max, base, cap int
	var kind string
	var purged bool
	var worker int64
	e = tx.QueryRow(`SELECT j.attempts+1,j.max_attempts,q.backoff_kind,q.backoff_base,COALESCE(q.backoff_max,0),j.leased_by,j.purge_requested FROM jobs j JOIN queues q ON q.id=j.queue_id WHERE j.id=$1 AND j.state='leased' AND j.lease_token=$2 AND j.lease_expires_at > $3 FOR UPDATE OF j`, id, token, now).Scan(&attempts, &max, &kind, &base, &cap, &worker, &purged)
	if e != nil {
		return e
	}
	state := "retry_wait"
	if !retry || attempts >= max || purged {
		state = "dead"
	}
	wait := Backoff(kind, base, attempts, cap)
	if delay != nil {
		wait = time.Duration(*delay) * time.Second
	}
	_, e = tx.Exec(`UPDATE jobs SET state=$2,event_at=$6,attempts=$3,last_error=$4,run_at=$5,finished_at=CASE WHEN $2='dead' THEN $6::timestamptz ELSE NULL END,lease_token=NULL,leased_by=NULL,lease_expires_at=NULL WHERE id=$1`, id, state, attempts, message, now.Add(wait), now)
	if e != nil {
		return e
	}
	_, e = tx.Exec(`INSERT INTO attempts SELECT $1,(SELECT count(*)+1 FROM attempts WHERE job_id=$1),$2,leased_at,$3,'failed',$4 FROM jobs WHERE id=$1`, id, worker, now, message)
	if e != nil {
		return e
	}
	if e = tx.Commit(); e != nil {
		return e
	}
	if state == "dead" {
		return j.Notify(id, now)
	}
	return nil
}
