	var lease struct {
		Jobs []struct {
			ID    int64  `json:"id"`
			Token string `json:"lease_token"`
		}
	}
	must(c.JSON("POST", "/v1/queues/"+name+"/lease", map[string]any{"worker_id": w["worker_id"], "max_jobs": 1}, &lease))
