package client

import (
	"bytes"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"os"
	"time"
)

type Client struct{ URL, Key string }

func Env() *Client {
	url := os.Getenv("QUEUELET_URL")
	if url == "" {
		url = "http://localhost:18200"
	}
	key := os.Getenv("QUEUELET_KEY")
	if key == "" {
		key = "acme-key"
	}
	return &Client{url, key}
}
func (c *Client) Do(method, path string, data any) ([]byte, int, error) {
	var body io.Reader
	if data != nil {
		b, e := json.Marshal(data)
		if e != nil {
			return nil, 0, e
		}
		body = bytes.NewReader(b)
	}
	req, e := http.NewRequest(method, c.URL+path, body)
	if e != nil {
		return nil, 0, e
	}
	req.Header.Set("Authorization", "Bearer "+c.Key)
	req.Header.Set("Content-Type", "application/json")
	resp, e := (&http.Client{Timeout: 15 * time.Second}).Do(req)
	if e != nil {
		return nil, 0, e
	}
	defer resp.Body.Close()
	b, e := io.ReadAll(resp.Body)
	return b, resp.StatusCode, e
}
func (c *Client) JSON(method, path string, data, out any) error {
	b, status, e := c.Do(method, path, data)
	if e != nil {
		return e
	}
	if status >= 400 {
		return fmt.Errorf("HTTP %d: %s", status, b)
	}
	return DecodeJSON(b, out)
}

// DecodeJSON preserves numbers and requires one complete JSON document.
func DecodeJSON(b []byte, out any) error {
	if !json.Valid(b) {
		return fmt.Errorf("invalid JSON: expected one complete value")
	}
	decoder := json.NewDecoder(bytes.NewReader(b))
	decoder.UseNumber()
	return decoder.Decode(out)
}
package worker

import (
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"queuelet/internal/client"
	"testing"
)

func TestDecodedWorkerDefaults(t *testing.T) {
	for _, tc := range []struct {
		name, kind, payload string
		attempt             int
		wantFailure         bool
	}{
		{"sleep omitted", "sleep", `{}`, 1, false},
		{"sleep wrong type", "sleep", `{"seconds":"not a number"}`, 1, false},
		{"sleep numeric", "sleep", `{"seconds":0}`, 1, false},
		{"fail3 omitted", "fail3", `{}`, 3, true},
		{"fail3 exhausted", "fail3", `{}`, 4, false},
		{"fail3 wrong type", "fail3", `{"n":true}`, 3, true},
		{"fail3 zero default", "fail3", `{"n":0}`, 3, true},
		{"fail omitted", "fail", `{}`, 1, false},
		{"fail numeric", "fail", `{"n":1}`, 1, true},
		{"fail numeric exhausted", "fail", `{"n":1}`, 2, false},
		{"echo exact", "echo", `{"big":9007199254740993,"nested":[0.12345678901234567890123456789]}`, 1, false},
	} {
		t.Run(tc.name, func(t *testing.T) {
			srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
				w.Write([]byte(`{"payload":` + tc.payload + `}`))
			}))
			defer srv.Close()
			var job Job
			if err := (&client.Client{URL: srv.URL}).JSON("GET", "/job", nil, &job); err != nil {
				t.Fatal(err)
			}
			job.Kind, job.Attempt = tc.kind, tc.attempt
			result, err := perform(job)
			if (err != nil) != tc.wantFailure {
				t.Fatalf("failure=%v, want %v", err, tc.wantFailure)
			}
			if !tc.wantFailure {
				b, err := json.Marshal(result)
				if err != nil || string(b) != tc.payload {
					t.Fatalf("result=%s err=%v, want %s", b, err, tc.payload)
				}
			}
		})
	}
}
