// A purge waiting on one queue's row must not block another queue's purge.
// Checks may synchronize via database locks; public repros never do.
func TestL07PurgeIndependentQueue(t *testing.T) {
 a,b:=l07Make(t,\"queued\"),l07Make(t,\"queued\")
 observer:=l02Store(t)
 tx,err:=observer.DB.Begin();if err"'!=nil {t.Fatal(err)};defer tx.Rollback()
 if _,err=tx.Exec(`SELECT id FROM jobs WHERE id=$1 FOR UPDATE`,a.jid);err!=nil {t.Fatal(err)}
 blocked:=l02Store(t);blocked.DB.SetMaxOpenConns(1)
 app:=fmt.Sprintf("l07-purge-%d",a.jid)
 if _,err=blocked.DB.Exec(`SELECT set_config('"'application_name',"'$1,false)`,app);err!=nil {t.Fatal(err)}
 type result struct {n int64; err error}
 first:=make(chan result,1)
 go func(){n,err:=(&jobs.Service{S:blocked}).Purge(a.qid,time.Now());first<-result{n,err}}()
 deadline:=time.Now().Add(3*time.Second)
 for {
  var waiting bool
  if err=observer.DB.QueryRow(`SELECT EXISTS(SELECT 1 FROM pg_stat_activity WHERE application_name=$1 AND wait_event_type='"'Lock')"'`,app).Scan(&waiting);err!=nil {t.Fatal(err)}
  if waiting {break};if time.Now().After(deadline){t.Fatal("purge did not wait on held row")};time.Sleep(10*time.Millisecond)
 }
 second:=make(chan result,1)
 go func(){n,err:=(&jobs.Service{S:observer}).Purge(b.qid,time.Now());second<-result{n,err}}()
 select {case r:=<-second:if r.err!=nil || r.n!=1 {t.Fatal(r)};case <-time.After(3*time.Second):t.Fatal("unrelated queue serialized behind blocked purge")}
 if err=tx.Commit();err!=nil {t.Fatal(err)}
 select {case r:=<-first:if r.err!=nil || r.n!=1 {t.Fatal(r)};case <-time.After(3*time.Second):t.Fatal("purge failed to resume")}
 l07Call(t,a.c,"GET",a.path(),nil,404);l07Call(t,b.c,"GET",b.path(),nil,404)
}
GO
